<?php
namespace App\Http\Controllers;
use App\Models\User; use App\Services\ConfigurationResolver; use Illuminate\Http\Request;
class DashboardController extends Controller {
 public function index(Request $r,ConfigurationResolver $resolver){$u=$r->user();if($u->isSuperAdmin())return redirect()->route('admin.dashboard');$latest=$u->timeClocks()->with('breaks')->latest('clock_in')->first();$week=$u->timeClocks()->with('breaks')->whereBetween('clock_in',[now()->startOfWeek(),now()->startOfWeek()->addDays(4)->endOfDay()])->latest('clock_in')->get();$month=$u->timeClocks()->whereBetween('clock_in',[now()->startOfMonth(),now()->endOfMonth()])->get();$team=collect();if($u->hasPermission('team.view'))$team=User::where(fn($q)=>$q->where('manager_id',$u->id)->orWhereIn('department_id',$u->managedDepartmentIds()))->where('employeed',true)->whereKeyNot($u->id)->with(['timeClocks'=>fn($q)=>$q->whereDate('clock_in',today())->with('breaks')])->get();$breakConfig=$latest?($latest->applied_configuration['breaks']??$resolver->resolve($u,'breaks',$latest->clock_in)):$resolver->resolve($u,'breaks',today());$availableBreaks=collect($breakConfig['value']['options']??[])->where('active',true);return view('dashboard.index',compact('u','latest','week','month','team','availableBreaks'));}
 public function team(Request $r){abort_unless($r->user()->hasPermission('team.view'),403);$u=$r->user();$team=User::where(fn($q)=>$q->where('manager_id',$u->id)->orWhereIn('department_id',$u->managedDepartmentIds()))->where('employeed',true)->with('timeClocks')->get();return view('dashboard.team',compact('team'));}
}
